-- data_035_of_120.sql: intelligence dataset 2026-09-29, part 35 of 120. Run in order; safe to re-run.

insert into public.sports_teams (external_key, name, short_name, sport, league, country, city, stadium, stadium_capacity, stadium_capacity_source_url, founded_year, domain, ownership_type, ownership_summary, ownership_source_url, revenue, revenue_currency, revenue_season, revenue_source_name, revenue_source_url, valuation, valuation_currency, valuation_year, valuation_source_name, valuation_source_url, social_followers, social_as_of, social_source_url, social_platforms, notes, sources, verification, source)
  values ('premier-league--crystal-palace', 'Crystal Palace Football Club', 'Crystal Palace', 'football', 'Premier League', 'England', 'London', 'Selhurst Park', 25194, 'https://stadiumdb.com/stadiums/eng/selhurst_park', 1905, 'cpfc.co.uk', 'consortium', 'Owned by a consortium of individuals: New York Jets owner Woody Johnson (43%, bought John Textor''s Eagle Football stake in 2025), Josh Harris and David Blitzer (18% each since 2015) and chairman Steve Parish (just over 10%). In June 2026 the FT reported the owners had appointed Raine Group to explore options including a full sale.', 'https://www.wearepalace.uk/club/owners/', 196600000, 'GBP', '2024-25', 'The Swiss Ramble', 'https://swissramble.substack.com/p/crystal-palace-finances-202425', 790000000, 'USD', 2025, 'Forbes (via SI)', 'https://www.si.com/soccer/every-premier-league-club-valuation-ranked', 6700000, null, 'https://www.givemesport.com/premier-league-clubs-followers-ranked/', '[{"platform": "Instagram", "followers": 2000000, "as_of": "2026-09-28", "source_url": "https://www.instagram.com/cpfc/"}]'::jsonb, 'Ownership under review: in June 2026 the FT (via Irish Times / Inside Croydon) reported the owners had appointed Raine Group to run a process that could include a full sale or a controlling stake, alongside stadium-financing options ahead of a second European season. Stake figures vary by source: Wikipedia''s 2025-26 season page lists Johnson 45% / Harris 10% / Blitzer 10% / Parish 10%, while wearepalace.uk and the FT-derived reports give Johnson 43%, Harris and Blitzer 18% each (30% combined per FT) and Parish 10% or slightly over; the latter set is used here. Textor''s stake is described as 43% or about 45% depending on source. Valuations diverge: Forbes 2025 $790m (ranked 29th); Sportico June 2025 $610m (50th globally); Forbes 2026 keeps Palace at 29th, reported by LondonWorld as around £595m including stadium debt (USD figure not found); the Johnson deal implied £550m. Revenue: club-record £196.6m in 2024-25 (Swiss Ramble; MatchdayFinance rounds to £197m) with operating costs of £239.1m, so the club made a loss. Palace is not in the Deloitte Money League top 20. A 2019 sale memo by Zenith Global Capital Partners marketed 75-90% of the club at a £210m valuation; no deal resulted. Harris and Blitzer invest personally (not via Apollo/Blackstone funds), so no PE fund is recorded as an institutional investor. Selhurst Park capacity is quoted between 25,194 and about 26,000 by different sources; the Main Stand rebuild (started January 2026, Goldman Sachs £125m loan) takes it above 34,000. Social total of 6.7m (givemesport) has no stated as-of date.', '["https://www.sportico.com/business/team-sales/2025/crystal-palace-sale-woody-johnson-1234857577/", "https://www.nfl.com/news/jets-owner-woody-johnson-buys-43-stake-in-english-soccer-club-crystal-palace", "https://www.forbes.com/sites/robertolsen-1/2025/06/23/new-york-jets-billionaire-co-owner-buys-stake-in-crystal-palace-fc/", "https://www.espn.com/soccer/story/_/id/45813769/jets-owner-johnson-completes-purchase-stake-crystal-palace", "https://swissramble.substack.com/p/crystal-palace-finances-202425", "https://www.matchdayfinance.com/post/crystal-palace-financial-results-2024-25", "https://www.si.com/soccer/every-premier-league-club-valuation-ranked", "https://www.forbes.com/teams/crystal-palace/", "https://www.forbes.com/sites/justinteitelbaum/2026/05/29/the-worlds-most-valuable-soccer-teams-2026/", "https://www.londonworld.com/sport/football/crystal-palace/crystal-palace-club-valuation-2025-5258734", "https://www.instagram.com/cpfc/", "https://www.givemesport.com/premier-league-clubs-followers-ranked/", "https://stadiumdb.com/stadiums/eng/selhurst_park", "https://en.wikipedia.org/wiki/Crystal_Palace_F.C.", "https://www.cpfc.co.uk/crystal-palace-main-stand-redevelopment/", "https://www.cityam.com/who-owns-crystal-palace-now-how-much-did-john-textor-josh-harris-and-david-blitzer-and-his-co-owners-pay/", "https://www.johntextor.org/premier-league-statement", "https://www.sportbusiness.com/news/crystal-palace-confirms-investment-deal-with-american-businessmen/", "https://www.jonesday.com/en/practices/experience/2015/12/david-blitzer-and-josh-harris-make-significant-investment-in-crystal-palace-football-club", "https://www.bloomberg.com/news/articles/2015-12-19/apollo-s-josh-harris-completes-purchase-of-crystal-palace-soccer", "https://www.wearepalace.uk/club/owners/", "https://www.irishtimes.com/business/2026/06/16/us-billionaire-owners-of-crystal-palace-explore-sale/", "https://insidecroydon.com/2026/06/16/ft-reports-palaces-us-billionaire-owners-look-to-sell-shares/", "https://www.sportspro.com/news/crystal-palace-news-sale-document-parish-harris-blitzer/", "https://stadiumdb.com/news/2025/12/england_multimillion_loan_clears_the_way_for_selhurst_park_project_to_begin_in_january", "https://footballgroundguide.com/news/crystal-palace-secure-125m-boost-as-long-awaited-selhurst-park-redevelopment-finally-moves-forward.html"]'::jsonb, '[]'::jsonb, 'web_research')
  on conflict (external_key) do update set name = excluded.name, short_name = excluded.short_name, sport = excluded.sport, league = excluded.league, country = excluded.country, city = excluded.city, stadium = excluded.stadium, stadium_capacity = excluded.stadium_capacity, stadium_capacity_source_url = excluded.stadium_capacity_source_url, founded_year = excluded.founded_year, domain = excluded.domain, ownership_type = excluded.ownership_type, ownership_summary = excluded.ownership_summary, ownership_source_url = excluded.ownership_source_url, revenue = excluded.revenue, revenue_currency = excluded.revenue_currency, revenue_season = excluded.revenue_season, revenue_source_name = excluded.revenue_source_name, revenue_source_url = excluded.revenue_source_url, valuation = excluded.valuation, valuation_currency = excluded.valuation_currency, valuation_year = excluded.valuation_year, valuation_source_name = excluded.valuation_source_name, valuation_source_url = excluded.valuation_source_url, social_followers = excluded.social_followers, social_as_of = excluded.social_as_of, social_source_url = excluded.social_source_url, social_platforms = excluded.social_platforms, notes = excluded.notes, sources = excluded.sources, verification = excluded.verification, source = excluded.source;
